def UNITS(grade):
    return {11: G11, 12: G12}[grade]()


def G(area, sort, slug, q, topic, *a, **k):
    return PU(area, sort, slug, topic, *a, course=GS, q=q, **k)


def GC(area, sort, slug, q, topic, src, std, **k):
    return CP(area, sort, slug, src, std, topic=topic, course=GS, q=q, **k)


def E(course, area, sort, slug, q, topic, *a, **k):
    return PU(area, sort, slug, topic, *a, course=course, q=q, **k)


def EC(course, area, sort, slug, q, topic, src, std, **k):
    return CP(area, sort, slug, src, std, topic=topic, course=course, q=q, **k)


